p=Path(__file__).resolve().parent; chapters=json.loads((p/'chapters.json').read_text());Q=[]
def mc(n,q,o,a,x,tag='Concept MCQ'): Q.append(dict(chapter=str(n),type='mcq',marks=1,q=q,options=o,answer=a,explanation=x,tag=tag))
def num(n,q,a,m=4,tag='Numerical'):Q.append(dict(chapter=str(n),type='numerical',marks=m,q=q,solution=a,tag=tag))
def th(n,q,a,m=4,tag='Theory'):Q.append(dict(chapter=str(n),type='theory',marks=m,q=q,solution=a,tag=tag))
